INSERT IGNORE INTO `disease_info`
  (code, name_cn, name_en, category, pathogen, symptoms, causes, treatment, prevention, severity)
VALUES
  ('Aloe_Healthy', '芦荟·健康', 'Aloe Healthy', 'PHYSIOLOGICAL', NULL, '叶片颜色均匀、质地饱满，无斑点或畸形。', NULL, '无需处理。保持现状即可：按当前浇水节奏、维持现有光照位置。', '定期翻看叶片背面，早发现早处理；换季时注意通风。', 'LOW'),
  ('Aloe_Sunburn', '芦荟·晒伤', 'Aloe Sunburn', 'PHYSIOLOGICAL', NULL, '叶面出现大面积褪绿、发白或焦褐色斑块，多集中在朝向直射光的一侧，边界较清晰。', '突然搬到强光下、或隔着玻璃长时间直晒；夏季正午直射光。', '1. 移到明亮散射光处，避免正午直射\n2. 晒伤组织不可逆，只剪掉完全焦枯的叶片\n3. 保持正常浇水，不要为了补救而多浇\n4. 一周内不要施肥，等新叶长出再恢复', '换位置要循序渐进，先散光一周再逐步见光；夏季中午拉一层纱帘。', 'MEDIUM'),
  ('Aloe_Leaf_Spot', '芦荟·叶斑病', 'Aloe Leaf Spot', 'FUNGAL', '多为真菌（Alternaria / Cercospora 等）', '叶片上出现圆形或近圆形褐色斑点，边缘常有黄晕，后期斑点连成片。', '高温高湿、叶面长期带水、通风差；浇水时溅到叶片。', '1. 剪除病斑严重的叶片并丢弃（不要留在盆土上）\n2. 浇水改浇土面，停止叶面喷水\n3. 加强通风，拉开株距\n4. 病斑持续扩大时使用广谱杀菌剂（如代森锰锌），按说明稀释', '避免叶面长期积水；浇水后保持通风；新植株先隔离观察两周。', 'MEDIUM'),
  ('Aloe_Anthracnose', '芦荟·炭疽病', 'Aloe Anthracnose', 'FUNGAL', '炭疽菌 Colletotrichum 属', '叶片出现凹陷的、边缘深褐的圆形病斑，病斑上可见同心轮纹或黑色小点（分生孢子盘）。', '高温高湿季节；伤口（修剪、虫咬）后感染；叶面积水。', '1. 立即剪除病叶，剪刀每次使用后用酒精消毒\n2. 与健康植株隔离\n3. 停止叶面喷水，加强通风降低湿度\n4. 严重时使用咪鲜胺或苯醚甲环唑类杀菌剂', '修剪后伤口避免沾水；保持通风；避免过度密植。', 'HIGH'),
  ('Aloe_Rust', '芦荟·锈病', 'Aloe Rust', 'FUNGAL', '锈菌（Puccinia / Uromyces 等）', '叶背出现橙黄色至锈褐色粉末状孢子堆，正面有对应褪绿斑，触碰会掉粉。', '通风不良、湿度高、昼夜温差大；植株长势弱。', '1. 剪除并销毁严重感染的叶片\n2. 与其他植物隔离，孢子极易随风传播\n3. 改善通风，降低环境湿度\n4. 使用三唑类杀菌剂（如戊唑醇），喷叶背', '保持通风；避免叶片长期潮湿；发现即隔离。', 'MEDIUM'),
  ('Chrysanthemum_Healthy', '菊花·健康', 'Chrysanthemum Healthy', 'PHYSIOLOGICAL', NULL, '叶片颜色均匀、质地饱满，无斑点或畸形。', NULL, '无需处理。保持现状即可：按当前浇水节奏、维持现有光照位置。', '定期翻看叶片背面，早发现早处理；换季时注意通风。', 'LOW'),
  ('Chrysanthemum_Bacterial_Leaf_Spot', '菊花·细菌性叶斑病', 'Chrysanthemum Bacterial Leaf Spot', 'BACTERIAL', '黄单胞菌 Xanthomonas 等细菌', '叶片出现水渍状小点，迅速扩大为褐色或黑色不规则斑，边缘有黄色晕圈，潮湿时可见菌脓。', '高温高湿；叶面伤口；浇水飞溅传播。', '1. 剪除病叶并销毁，工具用酒精消毒\n2. 立即隔离，细菌病害传染极快\n3. 停止叶面浇水，保持叶面干燥\n4. 铜制剂（如氢氧化铜）可抑制，但注意浓度以免药害', '避免叶面喷水；工具定期消毒；新植株隔离观察。', 'HIGH'),
  ('Chrysanthemum_Septoria_Leaf_Spot', '菊花·斑枯病', 'Chrysanthemum Septoria Leaf Spot', 'FUNGAL', 'Septoria 属真菌', '下部老叶先出现暗褐色小斑，逐渐扩大并有灰白中心，斑内可见黑色小粒点。', '高温高湿、植株过密、下部叶片通风不良。', '1. 摘除病叶，尤其是下部老叶\n2. 增加株间通风\n3. 浇水避免溅到叶片\n4. 必要时使用百菌清或代森锰锌', '及时清理下部老叶；保持通风；避免密植。', 'MEDIUM'),
  ('Hibiscus_Healthy', '扶桑·健康', 'Hibiscus Healthy', 'PHYSIOLOGICAL', NULL, '叶片颜色均匀、质地饱满，无斑点或畸形。', NULL, '无需处理。保持现状即可：按当前浇水节奏、维持现有光照位置。', '定期翻看叶片背面，早发现早处理；换季时注意通风。', 'LOW'),
  ('Hibiscus_Blight', '扶桑·枯萎病', 'Hibiscus Blight', 'FUNGAL', '镰刀菌 / 疫霉菌等', '叶片自边缘或顶部开始大面积褐变干枯，发展迅速，可累及整株。', '盆土过湿、根系受损、通风差；高温高湿。', '1. 剪除枯死组织，检查根系是否腐烂\n2. 控水，等盆土表层干透再浇\n3. 改善通风，降低湿度\n4. 若根部已腐，脱盆剪除烂根、换新土重栽', '避免盆土长期积水；保证排水良好；定期通风。', 'HIGH'),
  ('Hibiscus_Necrosis', '扶桑·叶坏死', 'Hibiscus Necrosis', 'PHYSIOLOGICAL', NULL, '叶尖或叶缘组织干枯变褐、变脆，与健康组织间有明确的褐色分界线。', '空气干燥、浇水不均、盐分积累（长期不换土或施肥过量）、水质偏硬。', '1. 剪掉干枯部分（留 1-2mm 以免伤及健康组织）\n2. 检查浇水是否规律——忽干忽湿最容易焦边\n3. 用纯净水或晾晒过的自来水浇灌\n4. 每 1-2 年换一次土，冲洗掉积累的盐分\n5. 增加环境湿度（加湿器或托盘放湿石）', '规律浇水；避免施肥过量；保持环境湿度 50% 以上。', 'MEDIUM'),
  ('Hibiscus_Scorch', '扶桑·日灼', 'Hibiscus Scorch', 'PHYSIOLOGICAL', NULL, '叶片出现大面积浅褐色干枯区，多在受光面，组织呈纸质脆感。', '强光直射 + 供水不足；夏季高温。', '1. 移到散射光处或加遮阴\n2. 补足水分，但避免一次性大水\n3. 剪除完全枯焦的叶片\n4. 高温期避免正午浇水（应选清晨或傍晚）', '夏季遮阴；保持水分供应稳定。', 'MEDIUM'),
  ('Money_Plant_Healthy', '绿萝·健康', 'Money Plant Healthy', 'PHYSIOLOGICAL', NULL, '叶片颜色均匀、质地饱满，无斑点或畸形。', NULL, '无需处理。保持现状即可：按当前浇水节奏、维持现有光照位置。', '定期翻看叶片背面，早发现早处理；换季时注意通风。', 'LOW'),
  ('Money_Plant_Manganese_Toxicity', '绿萝·锰中毒', 'Money Plant Manganese Toxicity', 'PHYSIOLOGICAL', NULL, '叶脉间出现褐色或黑色细小斑点，叶片发黄，严重时斑点连片、叶缘卷曲。', '基质或灌溉水锰含量过高；土壤偏酸（pH < 5.5）时锰溶解度上升；长期积水加剧吸收。', '1. 停止可能含锰的肥料\n2. 提高基质 pH：换用偏中性基质，或少量添加园艺石灰\n3. 用干净水源浇灌，避免长期使用偏酸的自来水\n4. 症状严重的叶片可剪除，但保留大部分叶片维持光合', '注意基质 pH；避免过量施用含微量元素的肥料；定期换土。', 'MEDIUM'),
  ('Money_Plant_Bacterial_Wilt', '绿萝·细菌性枯萎病', 'Money Plant Bacterial Wilt', 'BACTERIAL', '青枯雷尔氏菌 Ralstonia 等', '叶片快速萎蔫发黄，茎部出现水渍状褐斑，严重时整株倒伏；切开茎部可见维管束变褐。', '土壤带菌；高温高湿；浇水过多造成根系伤口。', '1. 立即与其他植物隔离，避免通过工具和手部接触传播\n2. 剪除已明显发病的叶片和茎段，剪刀每次使用后消毒\n3. 停止叶面喷水，保持叶面干燥\n4. 改善通风，避免高温高湿\n5. 若病情持续恶化，考虑脱盆检查并销毁严重感染的植株', '使用干净基质；避免盆土长期积水；工具消毒。', 'HIGH'),
  ('Money_Plant_Chlorosis', '绿萝·黄化病', 'Money Plant Chlorosis', 'PHYSIOLOGICAL', NULL, '叶片整体或脉间发黄，叶脉常保持绿色，新叶老叶均可发生。', '缺铁/缺氮等营养问题；盆土偏碱；根系吸收受阻；浇水过多导致闷根。', '1. 先判断是新叶黄（缺铁等微量元素）还是老叶黄（缺氮/浇水问题）\n2. 检查盆土干湿：过湿先控水，等表层干透再浇\n3. 生长期补充含铁微量元素肥或通用液肥，按说明稀释\n4. 长期用自来水浇灌导致土壤偏碱时，可偶尔用稀释的柠檬酸水调节', '规律施肥；使用透气基质；避免长期积水。', 'MEDIUM'),
  ('Rose_Healthy', '月季·健康', 'Rose Healthy', 'PHYSIOLOGICAL', NULL, '叶片颜色均匀、质地饱满，无斑点或畸形。', NULL, '无需处理。保持现状即可：按当前浇水节奏、维持现有光照位置。', '定期翻看叶片背面，早发现早处理；换季时注意通风。', 'LOW'),
  ('Rose_Black_Spot', '月季·黑斑病', 'Rose Black Spot', 'FUNGAL', '蔷薇双壳菌 Diplocarpon rosae', '叶片出现放射状黑色圆斑，边缘呈毛刷状，周围组织变黄，后期大量落叶。', '雨水飞溅、叶面潮湿时间长、通风差；月季最常见的病害。', '1. 摘除所有病叶并彻底清理盆面落叶（病菌在此越冬）\n2. 浇水只浇土面，杜绝叶面溅水\n3. 增加通风和光照\n4. 严重时使用苯醚甲环唑或代森锰锌，7-10 天一次，连用 2-3 次', '选择抗病品种；保持叶面干燥；冬季清理落叶。', 'MEDIUM'),
  ('Rose_Insect_Damage', '月季·虫害', 'Rose Insect Damage', 'PEST', '蚜虫、红蜘蛛、介壳虫等', '叶片出现缺刻、卷曲、失绿小点或黏性分泌物；翻看叶背可见虫体或蛛网。', '通风不良；环境干燥；新购入植物未隔离。', '1. 先用湿布或棉签物理清除可见虫体\n2. 用清水冲洗叶背，重点冲叶背\n3. 红蜘蛛喜干怕湿：增加环境湿度并加强通风\n4. 虫量大时使用吡虫啉或阿维菌素，按说明使用；间隔 7 天再用一次以覆盖虫卵\n5. 与其他植物隔离至确认无虫', '新植株隔离两周；定期翻看叶背；保持通风。', 'MEDIUM'),
  ('Rose_Downy_Mildew', '月季·霜霉病', 'Rose Downy Mildew', 'FUNGAL', '霜霉菌（Peronospora 等）', '叶面出现淡黄绿色不规则斑块，叶背对应位置长出灰紫色霉层，多在早晨可见。', '低温高湿、通风不良、夜间叶面结露。', '1. 剪除病叶并清理落叶\n2. 降低环境湿度，避免夜间叶面结露\n3. 增加通风和光照\n4. 使用烯酰吗啉等霜霉专用药剂', '控制湿度；避免傍晚浇水；保持通风。', 'HIGH'),
  ('Rose_Mosaic_Virus', '月季·花叶病毒病', 'Rose Mosaic Virus', 'VIRAL', '花叶病毒（如月季花叶病毒 RMV）', '叶片出现黄绿相间的花叶斑纹，叶形畸变、皱缩，植株长势明显变弱。', '蚜虫等刺吸式害虫传播；嫁接或修剪工具带毒。', '1. 病毒病无法治愈，只能控制：立即隔离\n2. 剪除症状严重的枝叶，工具彻底消毒\n3. 防治蚜虫等传播媒介\n4. 症状持续加重的植株建议淘汰，避免传染其他植物', '购买无病毒苗木；工具消毒；及时防治蚜虫。', 'HIGH'),
  ('Rose_Powdery_Mildew', '月季·白粉病', 'Rose Powdery Mildew', 'FUNGAL', '白粉菌（Erysiphe / Podosphaera 等）', '叶面覆盖白色粉末状霉层，像撒了面粉，嫩叶常见畸形卷曲。', '通风差、光照不足、空气干燥但盆土偏湿。', '1. 剪除霉层严重的叶片\n2. 改善通风、增加光照\n3. 用枯草芽孢杆菌或硫制剂处理，严重时用小苏打水（1L 水 + 5g）喷施\n4. 避免偏施氮肥', '保持通风与光照；避免氮肥过量导致新叶徒长。', 'MEDIUM'),
  ('Rose_Rust', '月季·锈病', 'Rose Rust', 'FUNGAL', '锈菌（Puccinia / Uromyces 等）', '叶背出现橙黄色至锈褐色粉末状孢子堆，正面有对应褪绿斑，触碰会掉粉。', '通风不良、湿度高、昼夜温差大；植株长势弱。', '1. 剪除并销毁严重感染的叶片\n2. 与其他植物隔离，孢子极易随风传播\n3. 改善通风，降低环境湿度\n4. 使用三唑类杀菌剂（如戊唑醇），喷叶背', '保持通风；避免叶片长期潮湿；发现即隔离。', 'MEDIUM'),
  ('Rose_Yellow_Mosaic_Virus', '月季·黄化花叶病毒病', 'Rose Yellow Mosaic Virus', 'VIRAL', '花叶病毒（如月季花叶病毒 RMV）', '叶片出现黄绿相间的花叶斑纹，叶形畸变、皱缩，植株长势明显变弱。', '蚜虫等刺吸式害虫传播；嫁接或修剪工具带毒。', '1. 病毒病无法治愈，只能控制：立即隔离\n2. 剪除症状严重的枝叶，工具彻底消毒\n3. 防治蚜虫等传播媒介\n4. 症状持续加重的植株建议淘汰，避免传染其他植物', '购买无病毒苗木；工具消毒；及时防治蚜虫。', 'HIGH'),
  ('Turmeric_Healthy', '姜黄·健康', 'Turmeric Healthy', 'PHYSIOLOGICAL', NULL, '叶片颜色均匀、质地饱满，无斑点或畸形。', NULL, '无需处理。保持现状即可：按当前浇水节奏、维持现有光照位置。', '定期翻看叶片背面，早发现早处理；换季时注意通风。', 'LOW'),
  ('Turmeric_Blotch', '姜黄·斑点病', 'Turmeric Blotch', 'FUNGAL', '多为真菌（Alternaria / Cercospora 等）', '叶片上出现圆形或近圆形褐色斑点，边缘常有黄晕，后期斑点连成片。', '高温高湿、叶面长期带水、通风差；浇水时溅到叶片。', '1. 剪除病斑严重的叶片并丢弃（不要留在盆土上）\n2. 浇水改浇土面，停止叶面喷水\n3. 加强通风，拉开株距\n4. 病斑持续扩大时使用广谱杀菌剂（如代森锰锌），按说明稀释', '避免叶面长期积水；浇水后保持通风；新植株先隔离观察两周。', 'MEDIUM'),
  ('Turmeric_Leaf_Spot', '姜黄·叶斑病', 'Turmeric Leaf Spot', 'FUNGAL', '多为真菌（Alternaria / Cercospora 等）', '叶片上出现圆形或近圆形褐色斑点，边缘常有黄晕，后期斑点连成片。', '高温高湿、叶面长期带水、通风差；浇水时溅到叶片。', '1. 剪除病斑严重的叶片并丢弃（不要留在盆土上）\n2. 浇水改浇土面，停止叶面喷水\n3. 加强通风，拉开株距\n4. 病斑持续扩大时使用广谱杀菌剂（如代森锰锌），按说明稀释', '避免叶面长期积水；浇水后保持通风；新植株先隔离观察两周。', 'MEDIUM'),
  ('Turmeric_Aphid_Infestation', '姜黄·蚜虫危害', 'Turmeric Aphid Infestation', 'PEST', '蚜虫', '嫩梢和叶背聚集大量绿色或黑色小虫，叶片卷曲、发亮（蜜露），可能伴随蚂蚁。', '春秋季高发；通风不良；氮肥过量使新梢嫩绿。', '1. 用清水冲洗或用湿布擦除\n2. 少量时手工捏除即可\n3. 虫量大时用吡虫啉或苦参碱喷施，重点喷叶背和嫩梢\n4. 蚜虫会传播病毒病，务必早处理', '注意通风；避免氮肥过量；定期检查嫩梢。', 'MEDIUM'),
  ('Turmeric_Leaf_Necrosis', '姜黄·叶枯坏死', 'Turmeric Leaf Necrosis', 'PHYSIOLOGICAL', NULL, '叶尖或叶缘组织干枯变褐、变脆，与健康组织间有明确的褐色分界线。', '空气干燥、浇水不均、盐分积累（长期不换土或施肥过量）、水质偏硬。', '1. 剪掉干枯部分（留 1-2mm 以免伤及健康组织）\n2. 检查浇水是否规律——忽干忽湿最容易焦边\n3. 用纯净水或晾晒过的自来水浇灌\n4. 每 1-2 年换一次土，冲洗掉积累的盐分\n5. 增加环境湿度（加湿器或托盘放湿石）', '规律浇水；避免施肥过量；保持环境湿度 50% 以上。', 'MEDIUM');
